#include <stdio.h>
#include <string.h>

#define MAX_STR_LEN 50000

int lengthOfLongestSubstring(char* s) {
    int i = 0;
    int window_len = 0;
    int max_len = 0;
    int last_occ = 0;
    int cur_window_start = 1;
    int lookup_table[128] = {[0 ... 127] = 0};
    int str_len = strnlen(s, MAX_STR_LEN);

    for(i = 0; i < str_len; ++i){
        if((last_occ = lookup_table[(int)s[i]]) >= cur_window_start) {
            cur_window_start = last_occ + 1;
        }

        window_len = i + 2 - cur_window_start; 
        max_len = window_len > max_len ? window_len : max_len; 
        lookup_table[(int)s[i]] = i + 1; // i+1 , zero means no previous occurrence
    } 

    return max_len;
}

